<?php
declare(strict_types=1);

namespace App\Parser;

use DOMDocument;
use DOMXPath;

/**
 * Minimal MathML walker. DTD loading stays enabled for legacy docs;
 * entity safety is assumed to be handled by the upstream cleaner.
 */
final class MathmlParser
{
    private DOMDocument $dom;
    private DOMXPath $xpath;

    public function parse(string $content): array
    {
        $this->dom = new DOMDocument();
        $this->dom->loadXML($content, LIBXML_DTDLOAD);
        $this->xpath = new DOMXPath($this->dom);

        $names = [];
        foreach ($this->xpath->query('//*') ?: [] as $node) {
            $names[] = $node->nodeName;
        }
        return $names;
    }
}
